        self.node_id = node_id
        self.P = {node_id: 0}
        self.N = {node_id: 0}

    def _validate_delta(self, delta):
        """Ensure delta is a strict integer (not bool) and positive."""
        if isinstance(delta, bool) or not isinstance(delta, int):
            raise ValueError("delta must be an integer")
        if delta <= 0:
            raise ValueError("delta must be positive")

    def increment(self, delta=1):
        self._validate_delta(delta)
        if self.node_id not in self.P:
            self.P[self.node_id] = 0
        self.P[self.node_id] += delta

    def decrement(self, delta=1):
        self._validate_delta(delta)
        if self.node_id not in self.N:
            self.N[self.node_id] = 0
        self.N[self.node_id] += delta

    def value(self):
        return sum(self.P.values()) - sum(self.N.values())

    def merge(self, other):
        """Merge another PNCounter state using component-wise maximum.

        This guarantees idempotence, commutativity, and monotonicity.
        """
        if not isinstance(other, PNCounter):
            raise ValueError("other must be a PNCounter instance")

        # Merge P vectors
        all_p_nodes = set(self.P.keys()) | set(other.P.keys())
        for n in all_p_nodes:
            self.P[n] = max(self.P.get(n, 0), other.P.get(n, 0))

        # Merge N vectors
